package io.moli.android;

import android.app.*;
import android.content.Context;
import android.os.*;
import android.text.InputType;
import android.view.WindowManager;
import android.widget.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.concurrent.*;
import org.json.*;

/** Account/configuration adapter. All network and vehicle commands belong to Rust. */
final class HyundaiPanel {
    static final class State {JSONObject snapshot;String instance="hyundai-eu",error;Future<JSONObject> work;boolean changed,browser;long checked;String operation;}
    interface Dispatch {Future<JSONObject> run(JSONObject request,boolean mutate)throws Exception;}
    final Activity activity;final State state;final Runnable render,reload;final Dispatch dispatch;
    HyundaiPanel(Activity a,State s,Runnable render,Runnable reload){this(a,s,render,reload,null);}
    HyundaiPanel(Activity a,State s,Runnable render,Runnable reload,Dispatch dispatch){activity=a;state=s;this.render=render;this.reload=reload;this.dispatch=dispatch;}
    String str(int id){return activity.getString(id);}
    void text(LinearLayout p,String s){TextView v=new TextView(activity);v.setText(s);v.setTextSize(16);v.setTextColor(activity.getColor(R.color.management_ink));v.setPadding(12,12,12,12);p.addView(v);}
    Button button(LinearLayout p,int label,String tag,Runnable action){Button b=new Button(activity);b.setText(label);b.setAllCaps(false);b.setTag(tag);b.setMinHeight(48);b.setEnabled(state.work==null);b.setOnClickListener(v->action.run());p.addView(b);return b;}
    EditText field(LinearLayout p,int hint,int type,String value){EditText e=new EditText(activity);e.setHint(hint);e.setInputType(type);e.setText(value);e.setSaveEnabled(false);e.setImportantForAutofill(android.view.View.IMPORTANT_FOR_AUTOFILL_NO_EXCLUDE_DESCENDANTS);p.addView(e);return e;}
    void action(JSONObject request,boolean mutate){if(state.work!=null)return;state.error=null;state.changed=mutate;state.operation=request.optString("operation");Context app=activity.getApplicationContext();try{request.put("instance",state.instance);Callable<JSONObject> call=()->{JSONObject reply=new ConfigStore(app).hyundai(request);if(EngineHost.state()==EngineHost.State.RUNNING)try{reply.put("hub",WeatherBinding.snapshot());}catch(Exception ignored){}return reply;};state.work=dispatch!=null?dispatch.run(request,mutate):mutate?EngineHost.maintain(app,call):EngineHost.inspect(call);}catch(Exception e){state.error=str(R.string.hyundai_failed);}new Handler(Looper.getMainLooper()).post(render);}
    void load(){if(state.browser)return;try{action(new JSONObject().put("operation","status"),false);}catch(JSONException ignored){}}
    void complete(){
        if(state.work==null||!state.work.isDone())return;
        JSONObject browser=null;boolean configure=false;
        try{JSONObject reply=state.work.get();browser=reply.optJSONObject("browser_login");reply.remove("browser_login");state.snapshot=reply;
            JSONObject diagnostic=reply.optJSONObject("diagnostic");if(diagnostic!=null)state.error=diagnosticText(diagnostic);
            configure=Arrays.asList("login","complete_login","discover").contains(state.operation)&&reply.optBoolean("connected")&&diagnostic==null;
        }catch(Exception e){Throwable c=e instanceof ExecutionException?e.getCause():e;state.error=str(R.string.hyundai_failed)+" · "+safeCode(c==null?null:c.getMessage());}
        state.work=null;state.checked=SystemClock.elapsedRealtime();if(state.changed){state.changed=false;reload.run();}render.run();
        if(browser!=null){state.browser=true;String address=browser.optString("authorization_url");HyundaiSignIn.show(activity,address,(callback,failure)->{state.browser=false;try{JSONObject request=new JSONObject().put("operation",callback==null?"cancel_login":"complete_login").put("consent",true);if(callback!=null)request.put("callback",callback);if(failure!=null)request.put("failure",failure);action(request,true);}catch(JSONException ignored){}});}
        else if(configure)options();
    }
    String diagnosticText(JSONObject d){String phase=d.optString("phase");if(!Arrays.asList("setup","authorize","rsa_certificate","signin","signin_redirect","browser_authorize","browser_callback","cci_exchange","ccs_exchange","fleet_discovery","device_registration","pin","refresh","cooldown").contains(phase))phase="unavailable";String cause=safeCode(d.optString("cause"));String extra=d.optInt("http")>=100&&d.optInt("http")<=599?" · HTTP "+d.optInt("http"):"";String network=d.optString("network_phase");if(Arrays.asList("dns","connect","tls","headers","body").contains(network))extra+=" · "+network;return str(R.string.hyundai_failed)+" · "+phase+" / "+cause+extra;}
    static String safeCode(String c){return c!=null&&java.util.Arrays.asList("network","authentication","consent","captcha_or_block","certificate","protocol","unsupported","pin_rejected","storage","expired","rate_limit","cooldown","configuration","conflict","setup_not_confirmed","network_timeout","tls_failure","authorize_redirect_incomplete","signin_redirect_incomplete","provider_terms_required","redirect_not_allowed","redirect_limit","credentials_rejected","callback_invalid_or_expired","provider_page_failed").contains(c)?c:"unavailable";}
    void show(LinearLayout parent,JSONObject item)throws JSONException{
        JSONArray instances=item.optJSONArray("instances");if(instances!=null&&instances.length()>0){boolean found=false;for(int i=0;i<instances.length();i++)if(state.instance.equals(instances.getJSONObject(i).optString("id")))found=true;if(!found){state.instance=instances.getJSONObject(0).getString("id");state.snapshot=null;}}
        if(state.snapshot==null&&state.work==null)load();text(parent,str(R.string.hyundai_title));text(parent,str(R.string.hyundai_qualification));if(state.error!=null)text(parent,state.error);if(state.work!=null)text(parent,str(R.string.working));
        JSONObject s=state.snapshot;if(s!=null&&s.optBoolean("authorized_pending_discovery")){text(parent,str(R.string.hyundai_discovery_pending));text(parent,str("gspa".equals(s.optString("pending_api_mode"))?R.string.hyundai_mode_gspa:R.string.hyundai_mode_europe));button(parent,R.string.hyundai_discover,"hyundai:discover",()->{try{action(new JSONObject().put("operation","discover").put("consent",true),true);}catch(JSONException ignored){}});}
        if(s!=null){text(parent,str(s.optBoolean("connected")?R.string.hyundai_connected:R.string.hyundai_disconnected));if(s.optBoolean("connected")){text(parent,str(R.string.hyundai_phase)+" "+s.optString("phase"));text(parent,str("europe".equals(s.optString("api_mode"))?R.string.hyundai_mode_europe:R.string.hyundai_mode_gspa));text(parent,str(s.optJSONObject("options")!=null&&s.optJSONObject("options").optBoolean("commands_enabled")?R.string.hyundai_commands_on:R.string.hyundai_commands_off));JSONArray cars=s.optJSONArray("vehicles");for(int i=0;cars!=null&&i<cars.length();i++){JSONObject car=cars.getJSONObject(i);text(parent,car.optString("name")+" · "+car.optString("model"));}button(parent,R.string.hyundai_options,"hyundai:options",this::options);button(parent,R.string.hyundai_disconnect,"hyundai:disconnect",()->new AlertDialog.Builder(activity).setMessage(R.string.hyundai_disconnect_help).setNegativeButton(android.R.string.cancel,null).setPositiveButton(R.string.hyundai_disconnect,(d,w)->{try{action(new JSONObject().put("operation","disconnect").put("consent",true),true);}catch(JSONException ignored){}}).show());}}
        if(s!=null&&s.optJSONObject("hub")!=null){JSONArray drivers=s.optJSONObject("hub").optJSONArray("drivers");for(int i=0;drivers!=null&&i<drivers.length();i++){JSONObject driver=drivers.optJSONObject(i);if(state.instance.equals(driver.optString("instance"))&&driver.optJSONObject("status")!=null)text(parent,driver.optJSONObject("status").optString("reason",driver.optJSONObject("status").optString("state")));}}
        button(parent,R.string.hyundai_login,"hyundai:login",this::login);button(parent,R.string.hyundai_refresh,"hyundai:status",this::load);
    }
    LinearLayout form(){LinearLayout p=new LinearLayout(activity);p.setOrientation(LinearLayout.VERTICAL);p.setPadding(20,12,20,12);return p;}
    AlertDialog login(){
        LinearLayout p=form();text(p,str(R.string.hyundai_login_help));Spinner mode=new Spinner(activity);mode.setTag("hyundai:mode");mode.setAdapter(new ArrayAdapter<String>(activity,android.R.layout.simple_spinner_dropdown_item,new String[]{str(R.string.hyundai_mode_europe),str(R.string.hyundai_mode_gspa)}));mode.setSelection(state.snapshot!=null&&"gspa".equals(state.snapshot.optString("api_mode",state.snapshot.optString("pending_api_mode")))?1:0);p.addView(mode);
        EditText pin=field(p,R.string.hyundai_pin,InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_VARIATION_PASSWORD,"");pin.setTag("hyundai:pin");text(p,str(R.string.hyundai_browser_help));ScrollView scroll=new ScrollView(activity);scroll.addView(p);
        AlertDialog dialog=new AlertDialog.Builder(activity).setTitle(R.string.hyundai_login).setView(scroll).setNegativeButton(android.R.string.cancel,null).setNeutralButton(R.string.hyundai_password_login,null).setPositiveButton(R.string.hyundai_browser_login,null).create();
        dialog.setOnShowListener(d->{dialog.getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);
            dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{try{JSONObject req=loginRequest("begin_login",mode.getSelectedItemPosition(),pin.getText().toString());pin.setText("");dialog.dismiss();action(req,true);}catch(JSONException ignored){}});
            dialog.getButton(AlertDialog.BUTTON_NEUTRAL).setOnClickListener(v->{String selected=mode.getSelectedItemPosition()==0?"europe":"gspa",code=pin.getText().toString();pin.setText("");dialog.dismiss();passwordLogin(selected,code);});
        });dialog.setOnDismissListener(d->pin.setText(""));dialog.show();return dialog;
    }
    static JSONObject loginRequest(String operation,int mode,String pin)throws JSONException{return new JSONObject().put("operation",operation).put("api_mode",mode==0?"europe":"gspa").put("pin",pin).put("consent",true);}
    AlertDialog passwordLogin(String mode,String savedPin){
        LinearLayout p=form();text(p,str(R.string.hyundai_password_help));EditText user=field(p,R.string.hyundai_email,InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_EMAIL_ADDRESS,"");user.setTag("hyundai:username");EditText pass=field(p,R.string.hyundai_password,InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD,"");pass.setTag("hyundai:password");EditText pin=field(p,R.string.hyundai_pin,InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_VARIATION_PASSWORD,savedPin);pin.setTag("hyundai:pin");ScrollView scroll=new ScrollView(activity);scroll.addView(p);
        AlertDialog dialog=new AlertDialog.Builder(activity).setTitle(R.string.hyundai_password_login).setView(scroll).setNegativeButton(android.R.string.cancel,null).setPositiveButton(R.string.hyundai_login,null).create();dialog.setOnShowListener(d->{dialog.getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{if(user.length()==0||pass.length()==0)return;try{JSONObject req=loginRequest("login","europe".equals(mode)?0:1,pin.getText().toString()).put("username",user.getText().toString()).put("password",pass.getText().toString());user.setText("");pass.setText("");pin.setText("");dialog.dismiss();action(req,true);}catch(JSONException ignored){}});});dialog.setOnDismissListener(d->{user.setText("");pass.setText("");pin.setText("");});dialog.show();return dialog;
    }
    final class SourceChoice {
        final Spinner spinner;final ArrayList<String> ids=new ArrayList<>();
        SourceChoice(LinearLayout parent,int label,String unit,String selected){
            text(parent,str(label));spinner=new Spinner(activity);ArrayList<String> names=new ArrayList<>();ids.add("");names.add(str(R.string.hyundai_source_none));
            JSONObject hub=state.snapshot.optJSONObject("hub");JSONArray devices=hub==null?null:hub.optJSONArray("devices");
            for(int i=0;devices!=null&&i<devices.length();i++){JSONObject device=devices.optJSONObject(i);if("Hyundai".equals(device.optString("manufacturer")))continue;JSONArray points=device.optJSONArray("points");for(int j=0;points!=null&&j<points.length();j++){JSONObject point=points.optJSONObject(j);if(unit.equals(point.optString("unit"))&&point.optJSONObject("access")!=null&&point.optJSONObject("access").optBoolean("read")){String id=device.optString("id")+"/"+point.optString("key");ids.add(id);names.add(device.optString("native_name")+" · "+point.optString("label",point.optString("key")));}}}
            if(selected!=null&&!selected.isEmpty()&&!selected.equals("null")&&!ids.contains(selected)){ids.add(selected);names.add(str(R.string.hyundai_source_unavailable)+" · "+selected);}
            spinner.setAdapter(new ArrayAdapter<String>(activity,android.R.layout.simple_spinner_dropdown_item,names));spinner.setSelection(Math.max(0,ids.indexOf(selected)));parent.addView(spinner);
        }
        Object selected(){String id=ids.get(spinner.getSelectedItemPosition());return id.isEmpty()?JSONObject.NULL:id;}
    }
    void options(){JSONObject s=state.snapshot;if(s==null)return;JSONObject saved=s.optJSONObject("options");if(saved==null)saved=new JSONObject();LinearLayout p=form();text(p,str(R.string.hyundai_options_help));ArrayList<CheckBox> checks=new ArrayList<>();ArrayList<String> keys=new ArrayList<>();JSONArray cars=s.optJSONArray("vehicles"),selected=saved.optJSONArray("vehicles");for(int i=0;cars!=null&&i<cars.length();i++){JSONObject car=cars.optJSONObject(i);CheckBox c=new CheckBox(activity);c.setText(car.optString("name"));String key=car.optString("key");boolean on=selected==null||selected.length()==0;for(int j=0;selected!=null&&j<selected.length();j++)on|=key.equals(selected.optString(j));c.setChecked(on);p.addView(c);checks.add(c);keys.add(key);}
        EditText poll=field(p,R.string.hyundai_poll,InputType.TYPE_CLASS_NUMBER,""+saved.optLong("poll_seconds",900));EditText age=field(p,R.string.hyundai_age,InputType.TYPE_CLASS_NUMBER,""+saved.optLong("max_age_seconds",3600));CheckBox write=new CheckBox(activity);write.setText(R.string.hyundai_write_consent);write.setChecked(saved.optBoolean("commands_enabled"));p.addView(write);CheckBox gps=new CheckBox(activity);gps.setText(R.string.hyundai_gps_consent);gps.setChecked(saved.optBoolean("location_enabled"));p.addView(gps);text(p,str(R.string.hyundai_sources));SourceChoice weather=new SourceChoice(p,R.string.hyundai_weather,"°C",saved.optString("weather_point",""));SourceChoice meter=new SourceChoice(p,R.string.hyundai_meter,"kWh",saved.optString("dedicated_ev_meter",""));ScrollView scroll=new ScrollView(activity);scroll.addView(p);
        AlertDialog dialog=new AlertDialog.Builder(activity).setTitle(R.string.hyundai_options).setView(scroll).setNegativeButton(android.R.string.cancel,null).setPositiveButton(R.string.save,null).create();dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{try{JSONArray selection=new JSONArray();for(int i=0;i<checks.size();i++)if(checks.get(i).isChecked())selection.put(keys.get(i));if(selection.length()==0){text(p,str(R.string.hyundai_select_vehicle));return;}JSONObject options=new JSONObject().put("vehicles",selection).put("poll_seconds",Long.parseLong(poll.getText().toString())).put("max_age_seconds",Long.parseLong(age.getText().toString())).put("commands_enabled",write.isChecked()).put("location_enabled",gps.isChecked()).put("weather_point",weather.selected()).put("dedicated_ev_meter",meter.selected());if(options.getLong("poll_seconds")<900||options.getLong("max_age_seconds")<options.getLong("poll_seconds")){text(p,str(R.string.hyundai_options_help));return;}dialog.dismiss();action(new JSONObject().put("operation","configure").put("options",options).put("consent",true),true);}catch(Exception e){text(p,str(R.string.hyundai_failed));}}));dialog.show();}
}
